const dados = $json.body ?? $json;

if (dados.decisao !== 'aceita') return [];
if (!dados.data_hora_consulta) throw new Error('Horário da consultoria não informado.');

const data = String(dados.data_hora_consulta).replace(' ', 'T');
const dataParte = data.slice(0, 10);
const horaParte = data.slice(11, 16);
const [ano, mes, dia] = dataParte.split('-');
if (!ano || !mes || !dia || !/^\d{2}:\d{2}$/.test(horaParte)) {
  throw new Error('Formato do horário da consultoria inválido.');
}

const telefone = String(dados.telefone_cliente ?? '').replace(/\D/g, '');
if (!telefone) throw new Error('Telefone do cliente não informado.');

return [{
  json: {
    telefone,
    prompt: `Escreva uma mensagem curta e cordial em português brasileiro para ${dados.nome_cliente || 'o cliente'} informando que a consultoria jurídica foi aprovada para ${dia}/${mes}/${ano} às ${horaParte}. Peça que responda ACEITO para confirmar ou RECUSO para informar que não poderá comparecer. Não invente informações. Retorne somente o texto da mensagem, sem aspas ou formatação.`
  }
}];

const proposta = $('Preparar proposta').first().json;
const mensagem = String($json.output ?? $json.text ?? '').trim();
if (!mensagem) throw new Error('O agente Gemini não retornou o texto da proposta.');

return [{ json: { to: proposta.telefone, body: mensagem } }];

const evento = $json.body ?? $json;
const mensagens = Array.isArray(evento.messages) ? evento.messages : [];

return mensagens
  .filter(mensagem => !mensagem.from_me && mensagem.chat_id && mensagem.text?.body)
  .map(mensagem => ({
    json: {
      telefone: String(mensagem.chat_id).split('@')[0].replace(/\D/g, ''),
      mensagem: String(mensagem.text.body).trim()
    }
  }))
  .filter(item => item.json.telefone && item.json.mensagem);

const cliente = $('Ler resposta do cliente').item.json;
const texto = String($json.output ?? $json.text ?? '').trim();
if (!texto) throw new Error('O agente Gemini não retornou uma resposta para o cliente.');

let resultado;
try {
  const limpo = texto.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  resultado = JSON.parse(limpo);
} catch {
  throw new Error('O agente Gemini retornou uma resposta em formato inválido.');
}

const decisoes = ['aceita', 'recusada', 'duvida'];
if (!decisoes.includes(resultado.decisao) || typeof resultado.resposta !== 'string' || !resultado.resposta.trim()) {
  throw new Error('A resposta do agente Gemini não contém uma decisão e mensagem válidas.');
}

return [{ json: { to: cliente.telefone, body: resultado.resposta.trim() } }];
